'use client';

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { del, get, patch, post, type Page } from '@/lib/api/client';
import { usePagedList } from '@/lib/api/hooks';
import type { Catalog, CatalogImportReport, CatalogItem, KnowledgeBase, KnowledgeDocument, PassageHit, ProductHit } from '@/lib/api/types';

export const catalogKeys = {
  all: ['catalogs'] as const,
  list: () => ['catalogs', 'list'] as const,
  options: () => ['catalogs', 'options'] as const,
  one: (id: string) => ['catalogs', 'one', id] as const,
  items: (id: string) => ['catalogs', 'items', id] as const,
};

export const knowledgeKeys = {
  all: ['knowledge-bases'] as const,
  list: () => ['knowledge-bases', 'list'] as const,
  options: () => ['knowledge-bases', 'options'] as const,
  one: (id: string) => ['knowledge-bases', 'one', id] as const,
  documents: (id: string) => ['knowledge-bases', 'documents', id] as const,
  document: (id: string, documentId: string) => ['knowledge-bases', 'document', id, documentId] as const,
};

// ---------------------------------------------------------------- catalogs

export interface ItemInput {
  sku?: string;
  name: string;
  description?: string;
  category?: string | null;
  price?: number | null;
  stock?: number | null;
  available?: boolean;
  attributes?: Record<string, string>;
  tags?: string[];
  url?: string | null;
  imageUrl?: string | null;
}

export interface ImportInput {
  csv?: string;
  items?: Record<string, unknown>[];
  mode: 'upsert' | 'replace';
  dryRun: boolean;
}

export function useCatalogList() {
  return usePagedList<Catalog>(catalogKeys.list(), '/v1/catalogs');
}

/** Every catalog (for the assistant editor's picker): up to 100. */
export function useCatalogOptions() {
  return useQuery({ queryKey: catalogKeys.options(), queryFn: ({ signal }) => get<Page<Catalog>>('/v1/catalogs', { limit: 100 }, signal) });
}

export function useCatalog(id: string) {
  return useQuery({ queryKey: catalogKeys.one(id), queryFn: ({ signal }) => get<Catalog>(`/v1/catalogs/${id}`, undefined, signal) });
}

export function useCatalogItems(id: string, filters: { search: string; category: string }) {
  return usePagedList<CatalogItem>(catalogKeys.items(id), `/v1/catalogs/${id}/items`, { search: filters.search.trim() || undefined, category: filters.category || undefined });
}

/** What the assistant would find for a query (the searchProducts tool's results). */
export function useProductSearch(id: string, query: { q: string; maxPrice?: number; inStockOnly: boolean }, enabled: boolean) {
  return useQuery({
    queryKey: ['catalogs', 'search', id, query],
    enabled,
    staleTime: 0,
    queryFn: ({ signal }) => get<{ data: ProductHit[] }>(`/v1/catalogs/${id}/search`, { q: query.q, maxPrice: query.maxPrice, inStockOnly: query.inStockOnly ? 'true' : undefined }, signal),
  });
}

export function useCreateCatalog() {
  const client = useQueryClient();
  return useMutation({
    mutationFn: (body: { name: string; description?: string; currency?: string }) => post<Catalog>('/v1/catalogs', body),
    onSuccess: (catalog) => {
      client.setQueryData(catalogKeys.one(catalog.id), catalog);
      void client.invalidateQueries({ queryKey: catalogKeys.list() });
      void client.invalidateQueries({ queryKey: catalogKeys.options() });
    },
  });
}

export function useCatalogMutations(id: string) {
  const client = useQueryClient();
  /** Items changed: the list, the counts and categories, and the test search are stale. */
  const itemsChanged = () => {
    void client.invalidateQueries({ queryKey: catalogKeys.items(id) });
    void client.invalidateQueries({ queryKey: catalogKeys.one(id) });
    void client.invalidateQueries({ queryKey: catalogKeys.list() });
    void client.invalidateQueries({ queryKey: ['catalogs', 'search', id] });
  };
  return {
    update: useMutation({
      mutationFn: (body: { name?: string; description?: string; currency?: string }) => patch<Catalog>(`/v1/catalogs/${id}`, body),
      onSuccess: () => {
        void client.invalidateQueries({ queryKey: catalogKeys.one(id) });
        void client.invalidateQueries({ queryKey: catalogKeys.list() });
        void client.invalidateQueries({ queryKey: catalogKeys.options() });
      },
    }),
    remove: useMutation({
      mutationFn: () => del(`/v1/catalogs/${id}`),
      onSuccess: () => {
        client.removeQueries({ queryKey: catalogKeys.one(id) });
        void client.invalidateQueries({ queryKey: catalogKeys.list() });
        void client.invalidateQueries({ queryKey: catalogKeys.options() });
      },
    }),
    createItem: useMutation({ mutationFn: (body: ItemInput) => post<CatalogItem>(`/v1/catalogs/${id}/items`, body), onSuccess: itemsChanged }),
    updateItem: useMutation({ mutationFn: ({ itemId, body }: { itemId: string; body: Partial<ItemInput> }) => patch<CatalogItem>(`/v1/catalogs/${id}/items/${itemId}`, body), onSuccess: itemsChanged }),
    removeItem: useMutation({ mutationFn: (itemId: string) => del(`/v1/catalogs/${id}/items/${itemId}`), onSuccess: itemsChanged }),
    importItems: useMutation({
      mutationFn: (body: ImportInput) => post<CatalogImportReport>(`/v1/catalogs/${id}/import`, body),
      onSuccess: (report) => {
        if (!report.dryRun) itemsChanged();
      },
    }),
  };
}

// ---------------------------------------------------------------- knowledge bases

