export function useKnowledgeBaseMutations(id: string) {
  const client = useQueryClient();
  const documentsChanged = () => {
    void client.invalidateQueries({ queryKey: knowledgeKeys.documents(id) });
    void client.invalidateQueries({ queryKey: knowledgeKeys.one(id) });
    void client.invalidateQueries({ queryKey: knowledgeKeys.list() });
    void client.invalidateQueries({ queryKey: ['knowledge-bases', 'search', id] });
  };
  return {
    update: useMutation({
      mutationFn: (body: { name?: string; description?: string }) => patch<KnowledgeBase>(`/v1/knowledge-bases/${id}`, body),
      onSuccess: () => {
        void client.invalidateQueries({ queryKey: knowledgeKeys.one(id) });
        void client.invalidateQueries({ queryKey: knowledgeKeys.list() });
        void client.invalidateQueries({ queryKey: knowledgeKeys.options() });
      },
    }),
    remove: useMutation({
      mutationFn: () => del(`/v1/knowledge-bases/${id}`),
      onSuccess: () => {
        client.removeQueries({ queryKey: knowledgeKeys.one(id) });
        void client.invalidateQueries({ queryKey: knowledgeKeys.list() });
        void client.invalidateQueries({ queryKey: knowledgeKeys.options() });
      },
    }),
    createDocument: useMutation({
      mutationFn: (body: { title: string; content: string; sourceName?: string | null }) => post<KnowledgeDocument>(`/v1/knowledge-bases/${id}/documents`, body),
      onSuccess: documentsChanged,
    }),
    updateDocument: useMutation({
      mutationFn: ({ documentId, body }: { documentId: string; body: { title?: string; content?: string } }) => patch<KnowledgeDocument>(`/v1/knowledge-bases/${id}/documents/${documentId}`, body),
      onSuccess: (doc) => {
        client.setQueryData(knowledgeKeys.document(id, doc.id), doc);
        documentsChanged();
      },
    }),
    removeDocument: useMutation({ mutationFn: (documentId: string) => del(`/v1/knowledge-bases/${id}/documents/${documentId}`), onSuccess: documentsChanged }),
  };
}

// ---------------------------------------------------------------- files

/** Largest file the dashboard reads for an import or a document (the API's own limits apply after). */
export const MAX_FILE_BYTES = 8 * 1024 * 1024;

/** A text file's content (UTF-8), or an error message for the user. */
export async function readTextFile(file: File): Promise<{ text: string } | { error: string }> {
  if (file.size > MAX_FILE_BYTES) return { error: `The file is ${(file.size / 1024 / 1024).toFixed(1)} MB; the limit is 8 MB. Split it into smaller files.` };
  const text = await file.text();
  if (text.includes('\u0000')) return { error: 'This does not look like a text file. Save it as CSV (UTF-8), JSON, TXT or Markdown.' };
  return { text };
}
